[5245]="Troubled Spirits of Kel'Theril|56|53|10301|10304|5244|||i12896x1,i12897x1,i12898x1,i12899x1|1452|||1|||5|Use Jaron's Pick to find the four Highborne Relic Fragments. Bring them to Aurora Skycaller in Eastern Plaguelands.",
[5246]="Fragments of the Past|56|53|10304|10304|5245|||i13313x1|1423||||||4|Find the Sacred Highborne Writings in the Temple of Zin-Malor in Azshara, and bring them to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands.",
[5247]="Fragments of the Past|57|53|10304|10304|5246|||i11562x1,i12655x1,i16973x1|1423||||||3|Bring an Enchanted Thorium Bar, 5 Crystal Restore, and a Vial of Dire Water to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands.",
[5248]="Tormented By the Past|58|53|10304|10684|5247||||1423||||||2|Take the Crystal of Zin-Malor to Lake Kel'Theril in Winterspring and find a highborne spirit that will speak to you.",
